struct sock *sctp6_create_new_sock(struct sock *sk, struct sctp_association *asoc, bool kern) {
    struct sock *new_sk = NULL;
    struct sctp6_sock *new_sctp6 = NULL;

    /* Allocate a new socket. */
    new_sk = sk_alloc(sk->sk_family, GFP_KERNEL, kern);
    if (!new_sk) {
        return NULL;
    }

    /* Initialize the new socket with default values. */
    new_sk->sk_type = sk->sk_type;
    new_sk->sk_protocol = sk->sk_protocol;
    new_sk->sk_family = sk->sk_family;

    /* Allocate and initialize the SCTP6-specific data structure. */
    new_sctp6 = kzalloc(sizeof(*new_sctp6), GFP_KERNEL);
    if (!new_sctp6) {
        sk_free(new_sk);
        return NULL;
    }

    /* Copy relevant data from the existing socket. */
    new_sctp6->sctp = sctp_association_dup(asoc);
    if (!new_sctp6->sctp) {
        kfree(new_sctp6);
        sk_free(new_sk);
        return NULL;
    }

    /* Set up IPv6-specific parameters. */
    new_sctp6->ipv6only = 0; /* Default to dual-stack. */
    new_sctp6->sctp->base.sk = new_sk;

    /* Associate the SCTP6-specific data with the new socket. */
    new_sk->sk_user_data = new_sctp6;

    return new_sk;
}
